import{_ as t,H as i,f as a,i as o}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"11 | 从基础功能拆解RocketMQ的架构设计与实现","description":"","frontmatter":{},"headers":[{"level":2,"title":"RocketMQ 系统架构","slug":"rocketmq-系统架构","link":"#rocketmq-系统架构","children":[]},{"level":2,"title":"协议和网络模块","slug":"协议和网络模块","link":"#协议和网络模块","children":[]},{"level":2,"title":"数据存储","slug":"数据存储","link":"#数据存储","children":[{"level":3,"title":"元数据存储","slug":"元数据存储","link":"#元数据存储","children":[]},{"level":3,"title":"消息数据","slug":"消息数据","link":"#消息数据","children":[]}]},{"level":2,"title":"生产者和消费者","slug":"生产者和消费者","link":"#生产者和消费者","children":[{"level":3,"title":"生产端","slug":"生产端","link":"#生产端","children":[]},{"level":3,"title":"消费端","slug":"消费端","link":"#消费端","children":[]}]},{"level":2,"title":"HTTP 协议支持和管控操作","slug":"http-协议支持和管控操作","link":"#http-协议支持和管控操作","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"上节课思考闭环","slug":"上节课思考闭环","link":"#上节课思考闭环","children":[]}],"relativePath":"深入拆解消息队列47讲/11｜从基础功能拆解RocketMQ的架构设计与实现.md","filePath":"深入拆解消息队列47讲/11｜从基础功能拆解RocketMQ的架构设计与实现.md","lastUpdated":1795450178000}'),r={name:"深入拆解消息队列47讲/11｜从基础功能拆解RocketMQ的架构设计与实现.md"};function n(s,e,p,l,c,E){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="_11-从基础功能拆解rocketmq的架构设计与实现" tabindex="-1">11 | 从基础功能拆解RocketMQ的架构设计与实现 <a class="header-anchor" href="#_11-从基础功能拆解rocketmq的架构设计与实现" aria-label="Permalink to &quot;11 | 从基础功能拆解RocketMQ的架构设计与实现&quot;">​</a></h1><p>你好，我是文强。</p><p>上节课我们分析了 RabbitMQ 在通信协议、网络模块、存储模块、生产者、消费者这五个模块的设计思路。这节课我们用同一个思路来讲讲 RocketMQ。</p><p>有一个蛮有意思的现象，从我们的统计数据来看，RabbitMQ 的用户数是最多的。但是在程序员的口碑中，RocketMQ 无论是从性能还是稳定性上都是优于 RabbitMQ 的。从我个人来看，RocketMQ 可以当作 RabbitMQ 的替代品，因为 RocketMQ 在功能、稳定性、性能层面都比RabbitMQ 的表现更好。所以我们一起来看看为什么吧。</p><h2 id="rocketmq-系统架构" tabindex="-1">RocketMQ 系统架构 <a class="header-anchor" href="#rocketmq-系统架构" aria-label="Permalink to &quot;RocketMQ 系统架构&quot;">​</a></h2><p>在正式讲解之前，我们先来看一下 RocketMQ 的架构图。</p><p>如下图所示，RocketMQ 由 Producer、NameServer、Broker、Consumer 四大模块组成。其中，NameServer 是 RocketMQ 的元数据存储组件。另外，在 RocketMQ 5.0 后，还增加了Proxy 模块，用来支持 gRPC 协议，并为后续的计算存储分离架构做准备。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/1.jpeg" alt=""></a></p><p>RocketMQ 有 Topic、MessageQueue、Group 的概念，一个 Topic 可以包含一个或多个MessageQueue，一个 Group 可以订阅一个或多个 Topic。MessageQueue 是具体消息数据的存储单元，订阅的时候通过 Group 来管理消费订阅关系。</p><p>从流程上看，Broker 在启动的时候会先连接 NameServer，将各自的元数据信息上报给NameServer，NameServer 会在内存中存储元数据信息。客户端在连接集群的时候，会配置对应的 NameServer 地址，通过连接 NameServer 来实现客户端寻址，从而连接上对应的Broker。</p><p>客户端在发送数据的时候，会指定 Topic 或 MessageQueue。Broker 收到数据后，将数据存储到对应的 Topic 中，消息存储在 Topic 的不同 Queue 中。在底层的文件存储中，所有Queue 的数据是存储在同一个 CommitLog 文件中的。在订阅的时候会先创建对应的 Group，消费消息后，再确认数据。</p><p>从客户端来看，在 RocketMQ 5.0 以后，我们也可以通过直连 Proxy，将数据通过 gRPC 协议发送给 Proxy。Proxy 在当前阶段本质上只是一个代理（gRPC 协议的代理），不负责真正的数据存储，当收到数据后，还是将数据转发到 Broker 进行保存。</p><p>好了，学习完 RocketMQ 的基本概念和架构，我们继续围绕上述的五个模块来分析一下RocketMQ，先来看一下协议和网络模块。</p><h2 id="协议和网络模块" tabindex="-1">协议和网络模块 <a class="header-anchor" href="#协议和网络模块" aria-label="Permalink to &quot;协议和网络模块&quot;">​</a></h2><p>在协议方面，如下图所示，RocketMQ 5.0 之前支持自定义的 Remoting 协议，在 5.0 之后，增加了 gRPC 协议的支持。</p><p>这是在 Proxy 组件上完成了对 gRPC 协议的支持，用的是第 03 讲的代理（Proxy）模式。即 Broker 依旧只支持 Remoting 协议，如果需要支持 gRPC 协议，那么就需要单独部署Proxy 组件。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/2.jpeg" alt=""></a></p><p>在传输层协议方面，Remoting 和 gRPC 都是基于 TCP 协议传输的。Remoting 直接基于四层的 TCP 协议通信，gRPC 是基于七层的 HTTP2 协议通信，不过 HTTP2 底层也是基于TCP，它们本质上都是应用层的协议。</p><p>讲到这，不知道你是否会想：Remoting 不够用吗？为什么还需要 gRPC 呢？</p><p>在我看来，Remoting 从功能、性能、灵活性来看没有太大的问题。它的主要缺点是私有协议客户端的重复开发成本，以及与第三方服务集成的不便捷。因为是私有协议，所以 Remoting在多语言 SDK 开发时，基础网络模块的工作（如连接管理、网络模型设计、心跳管理等）都需要重新开发，工作量很高。另外，生态连接在 RocketMQ 是一个很重要的工作，gRPC 作为公有协议，有很多天然的生态集成能力，比如 Service Mesh、Kubernetes 生态等等。</p><p>关于 Remoting 协议的细节，我们在第 03 讲介绍协议时已经详细讲述了，这里不再重复。下面我们来聊一下 gRPC 协议，先来看一下 gRPC 的架构图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/3.png" alt=""></a></p><ul><li>图片来源：<a href="https://www.wallarm.com/what/the-concept-of-grpc" target="_blank" rel="noreferrer">https://www.wallarm.com/what/the-concept-of-grpc</a></li></ul><p>如上图所示，gRPC 分为 Client 端和 Server 端，底层基于 HTTP2 通信，内置了编解码模块，也定义好了 Client 和 Server 之间的调用方式，同时支持 TLS 加密，是一个完整的 RPC框架。所以我们可以看到它在底层已经实现了网络通信、协议的设计、编解码框架等所有基础的工作。从使用的角度来说，gRPC 提供了各个语言的开发库，只需要集成对应语言的开发库，即可完成网络模块的开发，很轻便。详情情况你可以参考 gRPC 各语言官方文档。</p><p>因为我们在第 04 讲就分析了 RocketMQ 网络模块的详细实现，这里就不重复讲了。接下来我们看一下 RocketMQ 的存储层。</p><h2 id="数据存储" tabindex="-1">数据存储 <a class="header-anchor" href="#数据存储" aria-label="Permalink to &quot;数据存储&quot;">​</a></h2><p>RocketMQ 同 RabbitMQ 一样，数据存储模块也分为元数据存储和消息数据存储两部分。</p><h3 id="元数据存储" tabindex="-1">元数据存储 <a class="header-anchor" href="#元数据存储" aria-label="Permalink to &quot;元数据存储&quot;">​</a></h3><p>先来看一下元数据存储。RocketMQ 的元数据信息实际是存储在 Broker 上的，Broker 启动时将数据上报到 NameServer 模块中汇总缓存。NameServer 是一个简单的 TCP Server，专门用来接收、存储、分发 Broker 上报的元数据信息。这些元数据信息是存储在 NameServer 内存中的，NameServer 不会持久化去存储这些数据。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/4.jpeg" alt=""></a></p><p>如上图所示，Broker 启动或删除时，会调用 NameServer 的注册和退出接口，每个 Broker 都会存储自己节点所属的元数据信息（比如有哪些 Topic、哪些 Queue 在本节点上），在 Broker启动时，会把全量的数据上报到 NameServer 中。</p><p>从部署形态上看，NameServer 是多节点部署的，是一个集群。 但是不同节点之间是没有相互通信的，所以本质上多个 NameServer 节点间数据没有一致性的概念，是各自维护自己的数据，由每台 Broker 上报元数据来维护每台 NameServer 节点上数据的准确性。</p><p>由于 NameServer 不负责具体消息数据的存储和分发，所以在请求频率、负载方面都不会很高。所以在大多数场景下，NameServer 都是可以多集群共享的。从功能上看，它对RocketMQ 的作用相当于 RabbitMQ 的 Mnesia。</p><p>讲完了元数据，我们再来看消息数据。</p><h3 id="消息数据" tabindex="-1">消息数据 <a class="header-anchor" href="#消息数据" aria-label="Permalink to &quot;消息数据&quot;">​</a></h3><p>RocketMQ 消息数据的最小存储单元是 MessageQueue，也就是我们常说的 Queue 或Partition。Topic 可以包含一个或多个 MessageQueue，数据写入到 Topic 后，最终消息会分发到对应的 MessageQueue 中存储。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/5.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/5.jpeg" alt=""></a></p><p>在底层的文件存储方面，并不是一个 MessageQueue 对应一个文件存储的，而是一个节点对应一个总的存储文件，单个 Broker 节点下所有的队列共用一个日志数据文件（CommitLog）来存储，和 RabbitMQ 采用的是同一种存储结构。存储结构如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/6.png" alt=""></a></p><ul><li>图片来源：<a href="https://github.com/apache/rocketmq/blob/develop/docs/cn/image/rocketmq_design_1.png" target="_blank" rel="noreferrer">https://github.com/apache/rocketmq/blob/develop/docs/cn/image/rocketmq_design_1.png</a></li></ul><p>图中主要包含 CommitLog、ConsumeQueue、IndexFile 三个跟消息存储相关的文件，下面我们来简单了解一下。</p><ul><li><p>CommitLog 是消息主体以及元数据存储主体，每个节点只有一个，客户端写入到所有MessageQueue 的数据，最终都会存储到这一个文件中。</p></li><li><p>ConsumeQueue 是逻辑消费队列，是消息消费的索引，不存储具体的消息数据。引入的目的主要是提高消息消费的性能。由于 RocketMQ 是基于主题 Topic 的订阅模式，消息消费是针对主题进行的，如果要遍历 Commitlog 文件，基于 Topic 检索消息是非常低效的。Consumer 可根据 ConsumeQueue 来查找待消费的消息，ConsumeQueue 文件可以看成是基于 Topic 的 CommitLog 索引文件。</p></li><li><p>IndexFile 是索引文件，它在文件系统中是以 HashMap 结构存储的。在 RocketMQ 中，通过 Key 或时间区间来查询消息的功能就是由它实现的。</p></li></ul><p>值得关注的是，因为消息数据会很多，CommitLog 会存储所有的消息内容。所以为了保证数据的读写性能，我们会对 CommitLog 进行分段存储。CommitLog 底层默认单个文件大小为1G，消息是顺序写入到文件中，当文件满了，就会写入下一个文件。对于 ConsumeQueue 和IndexFile，则不需要分段存储，因为它们存储的是索引数据，数据量一般很小。</p><p>在消息清理方面，RocketMQ 支持按照时间清理数据。这个时间是按照消息的生产时间计算的，和消息是否被消费无关，只要时间到了，那么数据就会被删除。</p><p>不过跟 RabbitMQ 不同的是，RocketMQ 不是按照主题或队列维度来清理数据的，而是按照节点的维度来清理的。原因和 RocketMQ 的存储模型有关，上面说到 RocketMQ 所有 Queue 的日志都存储在一个文件中，如果要支持主题和队列单独管理，需要进行数据的合并、索引的重建，实现难度相对复杂，所以 RocketMQ 并没有选择主题和队列这两个维度的清理逻辑。</p><p>好了，协议、网络、数据存储我们就都讲完了，接下来看一下 RocketMQ 客户端的生产者和消费者的实现。</p><h2 id="生产者和消费者" tabindex="-1">生产者和消费者 <a class="header-anchor" href="#生产者和消费者" aria-label="Permalink to &quot;生产者和消费者&quot;">​</a></h2><p>RocketMQ 的客户端连接服务端是需要经过客户端寻址的。如下图所示，首先和 NameServer完成寻址，拿到 Topic/MessageQueue 和 Broker 的对应关系后，接下来才会和 Broker 进行交互。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/7.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/7.jpeg" alt=""></a></p><h3 id="生产端" tabindex="-1">生产端 <a class="header-anchor" href="#生产端" aria-label="Permalink to &quot;生产端&quot;">​</a></h3><p>生产端的基础模块（如连接管理、心跳检测、协议构建、序列化等工作），则会以协议和网络层的设计为准，使用不同编程语言 SDK 完成对应的开发。例如，在 Java 中，我们可以使用Netty 来构建客户端，进行 TCP 通信，根据 Remoting 协议构建请求数据，序列化后向服务端发起请求，或者直接使用 gRPC 框架的客户端进行通信。</p><p>从生产端来看，生产者是将数据发送到 Topic 或者 Queue 里面的。如果是发送到 Topic，则数据要经历生产数据分区分配的过程。即决定消息要发送到哪个目标分区。</p><p>默认情况下，RocketMQ 支持轮询算法和最小投递延迟算法两种策略。默认是轮询算法，该算法保证了每个 Queue 中可以均匀地获取到消息。最小投递延迟算法会统计每次消息投递的时间延迟，然后根据统计出的结果将消息投递到时间延迟最小的 Queue。如果是直接发送到Queue，则无需经过分区选择，直接发送即可。</p><p>由于 RocketMQ 在协议层不支持批量发送消息的协议，所以在 SDK 底层是没有等待、聚合发送逻辑的。所以如果需要批量发送数据，就需要在生产的时候进行聚合，然后发送。</p><p>为了满足不同的发送场景，RocketMQ 支持单向发送、同步发送、异步发送三种发送形式。单向发送（Oneway）指发送消息后立即返回，不处理响应，不关心是否发送成功。同步发送（Sync）指发送消息后等待响应。异步发送（Async）指发送消息后立即返回，在提供的回调方法中处理响应。</p><h3 id="消费端" tabindex="-1">消费端 <a class="header-anchor" href="#消费端" aria-label="Permalink to &quot;消费端&quot;">​</a></h3><p>在 RocketMQ 消费端，为了满足不同场景的消费需要，RocketMQ 同时支持 Pull、Push、Pop 三种消费模型。</p><p>默认的消费模型是 Pull，Pull 的底层是以客户端会不断地去服务端拉取数据的形式实现的。Push 模型底层是以伪 Push 的方式实现的，即在客户端底层用一个 Pull 线程不断地去服务端拉取数据，拉到数据后，触发客户端设置的回调函数。让客户端从感受上看，是服务端直接将数据 Push 过来的。</p><p>另外，当消费者和分区都很多的时候，因为消费重平衡会消耗很长时间，且重平衡期间的消费会暂停。而在客户端也需要感知到复杂的重平衡行为，各个语言的客户端需要较高的重复开发成本。所以，RocketMQ 推出了 Pop 模式，将消费分区、分区分配关系、重平衡都移到了服务端，减少了重平衡机制给客户端带来的复杂性。</p><p>RocketMQ 默认是通过消费分组机制来消费的。即在客户端消费数据的时候，会通过消费分组来管理消费关系和存储消费进度。从实现上看，同一条消息支持被多个消费分组订阅，每个消费者分组可以有多个消费者。</p><p>由于 Topic 和 Queue 模型的存在，在启动消费的时候，就需要先分配消费者和分区消费关系。这个过程就是 RocketMQ 消费端负载均衡。在实现中，消息按照哪种逻辑分配给哪个消费者，就是由消费者负载均衡策略所决定的。</p><p>根据消费者类型的不同，消费者负载均衡策略分为消息粒度负载均衡和队列粒度负载均衡两种模式。这里简单了解下。</p><p>消息粒度负载均衡是指同一消费者分组内的多个消费者，将按照消息粒度平均分摊主题中的所有消息。即同一个队列中的消息，会被平均分配给多个消费者共同消费。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/8.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/8.jpeg" alt=""></a></p><p>队列粒度负载均衡是指同一消费者分组内的多个消费者，将按照队列粒度消费消息，即每个队列仅被一个消费者消费。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/9.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/9.jpeg" alt=""></a></p><p>消息粒度负载均衡就是我们之前在第 08 讲讲到的共享消费模式，而队列粒度负载均衡就是独占消费模式。大部分情况下，我推荐你优先使用队列粒度负载均衡。</p><p>当消费端消费数据成功后，就需要保存消费进度信息。RocketMQ 通过提交消费位点信息来保存消费进度。在服务端，RocketMQ 会为每个消费分组维护一份消费位点信息，信息中会保存消费的最大位点、最小位点、当前消费位点等内容。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/10.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/10.jpeg" alt=""></a></p><p>从实现来看，客户端消费完数据后，就会调用 Broker 的消费位点更新接口，提交当前消费的位点信息。</p><p>在服务端，消息被某个消费者消费完成后，不会立即在队列中被删除，以便当消费者客户端停止又再次重新上线时，会严格按照服务端保存的消费进度继续处理消息。如果服务端保存的历史位点信息已过期被删除，此时消费位点向前移动至服务端存储的最小位点。</p><p>讲完了生产者和消费者，接下来我们来看看 RocketMQ 对 HTTP 协议的支持和集群管控操作的实现。</p><h2 id="http-协议支持和管控操作" tabindex="-1">HTTP 协议支持和管控操作 <a class="header-anchor" href="#http-协议支持和管控操作" aria-label="Permalink to &quot;HTTP 协议支持和管控操作&quot;">​</a></h2><p>RocketMQ 原生不支持 HTTP 协议的生产消费，但是在一些云厂商的商业化版本是支持的。从技术上来看，HTTP 协议的支持和 gRPC 的支持可以是一个技术思路，即通过使用 Proxy 模式来实现。</p><p>同样的，RocketMQ 的管控也是不支持 HTTP 协议的操作的。RocketMQ 的管控操作都是通过Remoting 协议支持的，在 gRPC 协议中也不支持管控操作。即在 Broker 中，通过 Remoting协议暴露不同的接口或者在 NameServer 中暴露 TCP 的接口，来实现一些对应的管控操作。</p><p>客户端 SDK 会集成调用服务端这些接口的逻辑。命令行工具就是通过客户端 SDK 来完成管控操作，也可以在代码中通过 SDK 来执行管控操作。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/11.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B7%B1%E5%85%A5%E6%8B%86%E8%A7%A3%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%9747%E8%AE%B2/images/11/11.jpeg" alt=""></a></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>现在我们来总结一下 RocketMQ。</p><ol><li><p>协议层支持 Remoting 和 gRPC 两种协议。</p></li><li><p>网络层是基于 Java NIO 框架 Netty 开发，底层也是通过多路复用、异步 IO、Reactor 模型等技术来提高网络模块的性能。</p></li><li><p>存储层是基于多个 MessageQueue 的数据统一存储到一个文件的思路来设计的，同时也支持分段存储和基于时间的数据过期机制。</p></li><li><p>元数据存储是使用 Broker + 自定义的 NameServer 之间的配合来实现的。</p></li><li><p>客户端的访问需要经过客户端寻址机制，拿到元数据信息后，才直连 Broker。</p></li><li><p>生产端是将数据写入到 Topic 或分区，写入 Topic 时需要经过生产分区分配操作，确认最终写入的 MessageQueue 也支持多种写入方式。</p></li><li><p>消费端有消费分组的概念，也需要在多个消费者和消费分组之间进行消费的负载均衡，最后通过提交消费位点的形式来保存消费进度。</p></li></ol><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请你按照基础篇的思路，描述一下 RocketMQ 从生产到消费的全过程，越详细越好。</p><p>期待你的思考，如果觉得有收获，也欢迎你把这节课分享给身边的朋友。我们下节课再见！</p><h2 id="上节课思考闭环" tabindex="-1">上节课思考闭环 <a class="header-anchor" href="#上节课思考闭环" aria-label="Permalink to &quot;上节课思考闭环&quot;">​</a></h2><p>请你按照基础篇的课程思路，完整描述一下 RabbitMQ 从生产到消费的全过程？</p><p>跟经典的消息队列一样，RabbitMQ 的生产到消费总共经过生产者、Broker、消费者三个模块。大致的流程如下：</p><p>在生产端，客户端根据 AMQP 协议定义的命令字（如 Connection.Start/Start-Ok、Connection.Tune/Tune-Ok），通过四层的 TCP 协议和 Broker 创建 Connection、Channel 进行通信。客户端直连 Broker 服务，不需要经过寻址，然后客户端需要指定 Exchange、route_key 发送消息。因为 AMQP 没有支持批量发送的协议，消息会立即发送给给服务端。通信协议的内容格式、序列化和反序列化遵循 AMQP 的标准。</p><p>Broker 收到消息后，根据 AMQP 协议反序列化解析出请求内容。根据 Exchange 和route_key 的信息，结合路由模式，将数据分发到具体的 Queue 中。存储层收到消息后，底层会将这条数据的结构进行整合，添加一些额外信息，如写入时间等，然后将数据写入到同一个文件存储。Broker 支持数据过期机制，当消息过期后，数据会被删除。</p><p>消费端直接指定 Queue 消费，不需要经过消费分组、分区分配的过程。消费端跟生产端一样，根据 AMQP 协议连接上 Broker 后，消费端直接从 Queue 中消费数据，消费完成后通过手动 ACK 或自动 ACK 的方式 ACK 消息。</p>',89)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
